import fs from 'fs';
import path from 'path';
import { Command } from 'commander';
import { git } from '../utils/git.js';
import { readConfig } from '../utils/config.js';

export function registerImpact(program: Command) {
  program
    .command('impact')
    .description('Suggest potential impact of changes')
    .action(async () => {
      const diffSummary = await git().diffSummary(['--cached']);
      if (diffSummary.files.length === 0) {
        console.log('No staged changes.');
        return;
      }
      console.log('Change impact analysis:');
      diffSummary.files.forEach(file => {
        const ext = path.extname(file.file);
        let area = 'general';
        if (file.file.includes('package')) area = 'dependencies';
        else if (ext === '.ts' || ext === '.js') area = 'runtime logic';
        else if (ext === '.test.ts' || ext === '.spec.ts') area = 'tests';
        else if (file.file.includes('config')) area = 'configuration';
        console.log(`- ${file.file} -> likely affects ${area}`);
      });
      const importantFiles = ['jest.config.js', 'tsconfig.json', '.github/workflows'];
      const status = await git().status();
      const dirtyImportant = importantFiles.filter(f => status.modified.includes(f));
      if (dirtyImportant.length) {
        console.log('⚠️  Important config/test files changed but not staged:', dirtyImportant.join(', '));
      }
      const config = readConfig();
      if (config.linkedRepos && config.linkedRepos.length) {
        console.log('Cross-repo awareness: linked repos may be impacted:', config.linkedRepos.join(', '));
      }
    });
}
